import java.util.*;
public class Main {
 static class Fast {byte[] b=new byte[65536];int p,l;int read()throws Exception{if(p==l){l=System.in.read(b);p=0;if(l<0)return -1;}return b[p++];}int next()throws Exception{int c;do{c=read();}while(c<=32&&c!=-1);int x=0;while(c>32){x=x*10+c-48;c=read();}return x;}}
 public static void main(String[] args)throws Exception{Fast in=new Fast();int n=in.next(),m=in.next();int[] power=new int[m];for(int i=0;i<m;i++)power[i]=in.next();int[] head=new int[n+1],to=new int[2*m],next=new int[2*m];Arrays.fill(head,-1);for(int i=0;i<m;i++){int u=in.next(),v=in.next();to[2*i]=v;next[2*i]=head[u];head[u]=2*i;to[2*i+1]=u;next[2*i+1]=head[v];head[v]=2*i+1;}int[] time=new int[n+1],low=new int[n+1],parent=new int[n+1],edge=new int[n+1],it=head.clone(),stack=new int[n],weights=new int[m];Arrays.fill(edge,-1);int clock=0,count=0;for(int root=1;root<=n;root++){if(time[root]!=0)continue;int top=0;stack[0]=root;time[root]=low[root]=++clock;while(top>=0){int u=stack[top],e=it[u];if(e==-1){top--;if(edge[u]>=0){int p=parent[u];if(low[u]>time[p])weights[count++]=power[edge[u]];low[p]=Math.min(low[p],low[u]);}continue;}it[u]=next[e];int id=e/2;if(id==edge[u])continue;int v=to[e];if(time[v]==0){parent[v]=u;edge[v]=id;time[v]=low[v]=++clock;stack[++top]=v;}else low[u]=Math.min(low[u],time[v]);}}Arrays.sort(weights,0,count);long first=0,second=0;for(int i=0;i<count;i++)if(i%2==0)first+=weights[count-1-i];else second+=weights[count-1-i];System.out.println(first+" "+second);}
}